import sys

def solve():
    s = sys.stdin.readline().strip()
    if not s:
        print(-1)
        return

    max_len = 0
    stack = []
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()
                if stack:
                    current_len = i - stack[-1]
                else:
                    current_len = i + 1
                if current_len > max_len:
                    max_len = current_len
            else:
                stack.append(i)

    if max_len == 0:
        print(-1)
    else:
        print(max_len)

solve()
